findings.fix:
variable "target_size" {
  type        = number
  description = "The target number of running instances in the managed instance group."
  default     = 2
  validation {
    condition     = var.target_size > 0
    error_message = "target_size must be greater than 0."
  }
}

# in google_compute_region_instance_group_manager.region:
  target_size = var.target_size

update_policy {
  type                  = "PROACTIVE"
  minimal_action        = "REPLACE"
  max_surge_fixed       = length(var.distribution_policy_zones)
  max_unavailable_fixed = 0
}
